import{createEditorDialog,createDialogField,createDialogCheckbox,createDialogError}from"/js/modules/TipTap/EditorDialog.js";const ALLOWED_SCHEME=/^(https?|ftps?|mailto|tel|callto|sms|cid|xmpp):/i;const RELATIVE=/^[#/?]/;const SCHEME_SHAPED=/^[a-z][a-z0-9+.-]*:/i;const HOST_PORT=/^[^\s:/?#]+:\d+($|[/?#])/;const HOSTLIKE=/^(localhost([:/?#]|$)|[^\s/?#]+\.[^\s/?#]+)/i;function toHref(t){if(t===""||ALLOWED_SCHEME.test(t)||RELATIVE.test(t)){return t}if(SCHEME_SHAPED.test(t)&&!HOST_PORT.test(t)){return t}return HOST_PORT.test(t)||HOSTLIKE.test(t)?`https://${t}`:t}export function showLinkDialog(t){const e=Math.random().toString(36).slice(2,9);const o=t.getAttributes("link");const n=createDialogField(__("URL"),"url",`link-url-${e}`,o.href||"");const i=n.querySelector("input");i.placeholder="https://example.com";i.setAttribute("autocomplete","off");const r=createDialogCheckbox(__("Open in new tab"),`link-new-tab-${e}`,o.target==="_blank");const s=r.querySelector("input");const a=createDialogError(i,`link-error-${e}`);const{body:c}=createEditorDialog({editor:t,title:__("Insert/Edit link"),confirmLabel:__("Save"),onConfirm:({close:e})=>{const o=toHref(i.value.trim());if(o===""){t.chain().focus().extendMarkRange("link").unsetLink().run()}else{if(!t.can().setLink({href:o})){a.show(__("This URL is not accepted. Check the scheme (http, https, mailto, tel, ftp)."));i.focus();return}t.chain().focus().extendMarkRange("link").setLink({href:o,target:s.checked?"_blank":null}).run()}e()}});c.appendChild(n);c.appendChild(a.element);c.appendChild(r);i.focus()}